import{_ as e,o as n,c as l,a5 as r,j as t}from"./chunks/framework.QWVCgkrI.js";const c=JSON.parse('{"title":"LLMの連続バッチング（Continuous Batching）— 生成途中でリクエストをどう入れ替えるか","description":"","frontmatter":{"title":"LLMの連続バッチング（Continuous Batching）— 生成途中でリクエストをどう入れ替えるか","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"algorithms","summary":"到着時刻と出力長の異なる3リクエストで、固定バッチと反復ごとに入れ替える連続バッチングを比べる。","aliases":["連続バッチング","Continuous Batching","Iteration-level Scheduling","反復単位のスケジューリング","Orca"],"verification":"Orca、Sarathi-Serve、PagedAttentionの原論文に照合し、WindowsのPython 3.12.4でタイムラインと時刻・処理量の例を検算（2026-11-21）"}},"headers":[],"relativePath":"algorithms/continuous-batching.md","filePath":"algorithms/continuous-batching.md"}'),s={name:"algorithms/continuous-batching.md"};function o(i,a,d,g,u,h){return n(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="llmの連続バッチング-continuous-batching-—-生成途中でリクエストをどう入れ替えるか" tabindex="-1">LLMの連続バッチング（Continuous Batching）— 生成途中でリクエストをどう入れ替えるか <a class="header-anchor" href="#llmの連続バッチング-continuous-batching-—-生成途中でリクエストをどう入れ替えるか" aria-label="Permalink to &quot;LLMの連続バッチング（Continuous Batching）— 生成途中でリクエストをどう入れ替えるか&quot;">​</a></h1><p>同じLLMに、Aは一言の返事を、Bは長めの説明を頼みます。Aが先に書き終えた時点で、Cの依頼も届いています。Bが生成を続ける間、Aが使っていた実行枠をCに渡せるでしょうか。<strong>連続バッチング</strong>は、モデルを1回進めるたびに、同時に処理するリクエストの組を見直す方式です。<a href="https://www.usenix.org/conference/osdi22/presentation/yu" target="_blank" rel="noreferrer">YuらのOrca原論文 §3</a></p><h2 id="この記事で分かること" tabindex="-1">この記事で分かること <a class="header-anchor" href="#この記事で分かること" aria-label="Permalink to &quot;この記事で分かること&quot;">​</a></h2><p>3件のタイムラインから、固定バッチで空いた枠と、反復の境界で別のリクエストが入る枠の違いを説明できます。最初の出力を待つ時間、生成中の出力間隔、全体の処理量を分けて読めます。</p><h2 id="バッチを組み直す境界を変える" tabindex="-1">バッチを組み直す境界を変える <a class="header-anchor" href="#バッチを組み直す境界を変える" aria-label="Permalink to &quot;バッチを組み直す境界を変える&quot;">​</a></h2><p><strong>バッチ</strong>は、モデルがまとめて処理するリクエストの組です。ここでは、バッチをモデルに1回通して各列を先へ進めることを<strong>反復</strong>と呼びます。通常のdecodeでは、1列が一度の反復で次の出力を1トークン選びます。列ごとにそれまでの履歴を持ち、自分の続きを生成します。<a href="https://www.usenix.org/system/files/osdi22-yu.pdf#page=5" target="_blank" rel="noreferrer">YuらのOrca原論文 §2–3</a> · <a href="/study/algorithms/llm-prefill-and-decode.html">LLM推論のprefillとdecode</a></p><ul><li><strong>固定バッチ</strong>では、バッチの開始時にメンバーを決めます。途中で1件が終了しても、残りのメンバーが全員終わった後に次のバッチを始めます。</li><li><strong>連続バッチング</strong>では、反復が終わるたびに生成を終えた列を外し、続く列と待機中の列から次の組を作ります。すでに実行中の反復はその境界まで進みます。Orcaの論文では、この計算を割り当てる単位を<strong>反復単位のスケジューリング</strong>（iteration-level scheduling）と呼びます。<a href="https://www.usenix.org/system/files/osdi22-yu.pdf#page=5" target="_blank" rel="noreferrer">YuらのOrca原論文 §3 C1・S1</a></li></ul><p>ここで比べるのは、次のバッチに誰を入れるかです。固定バッチでも、実行エンジンと配信の仕組みが対応していれば、トークンが生成された時点で送れます。Orcaが比較対象として説明した従来型のインターフェースは、全員の完了後に応答を受け取る設計でした。<a href="https://www.usenix.org/system/files/osdi22-yu.pdf#page=5" target="_blank" rel="noreferrer">YuらのOrca原論文 §3 C1</a></p><h2 id="aの終了後、cはいつ参加できるか" tabindex="-1">Aの終了後、Cはいつ参加できるか <a class="header-anchor" href="#aの終了後、cはいつ参加できるか" aria-label="Permalink to &quot;Aの終了後、Cはいつ参加できるか&quot;">​</a></h2><p>図は、Aが0 ms、Bが0.5 ms、Cが2.5 msにサーバーへ届く場合です。AとCは2トークン、Bは5トークンで終了します。比較のため、両方式とも最初は1 msにA・Bで開始し、同時に処理できるのは2列までとします。どの反復も1 msで、各列の最初の反復には入力処理（prefill）と最初の出力をまとめて数えます。反復の終わりに、選んだトークンをすぐ送れると仮定します。</p>',10),t("figure",{style:{margin:"1rem 0"}},[t("div",{role:"img","aria-label":"到着はAが0ミリ秒、Bが0.5ミリ秒、Cが2.5ミリ秒。固定バッチではAは時刻2、3に出力し、Bは時刻2、3、4、5、6、待機したCは時刻7、8に出力する。連続バッチングではAとBの出力時刻は同じで、Cは時刻3に参加し、時刻4と5に出力する。",style:{display:"grid",gap:"0.6rem","max-width":"30rem","font-variant-numeric":"tabular-nums"}},[t("span",null,"到着（ms） A 0 ／ B 0.5 ／ C 2.5"),t("strong",null,"固定バッチ"),t("div",{style:{display:"grid","grid-template-columns":"3.4em repeat(7, minmax(0, 1fr))",gap:"0.22rem","text-align":"center"}},[t("span",{style:{"text-align":"left"}},"時刻"),t("span",null,"2"),t("span",null,"3"),t("span",null,"4"),t("span",null,"5"),t("span",null,"6"),t("span",null,"7"),t("span",null,"8"),t("strong",{style:{"text-align":"left"}},"A"),t("strong",{style:{"border-radius":"4px",background:"var(--vp-c-brand-soft)"}},"●"),t("strong",{style:{"border-radius":"4px",background:"var(--vp-c-brand-soft)"}},"◎"),t("span",null,"—"),t("span",null,"—"),t("span",null,"—"),t("span",null,"—"),t("span",null,"—"),t("strong",{style:{"text-align":"left"}},"B"),t("strong",{style:{"border-radius":"4px",background:"var(--vp-c-brand-soft)"}},"●"),t("strong",{style:{"border-radius":"4px",background:"var(--vp-c-brand-soft)"}},"●"),t("strong",{style:{"border-radius":"4px",background:"var(--vp-c-brand-soft)"}},"●"),t("strong",{style:{"border-radius":"4px",background:"var(--vp-c-brand-soft)"}},"●"),t("strong",{style:{"border-radius":"4px",background:"var(--vp-c-brand-soft)"}},"◎"),t("span",null,"—"),t("span",null,"—"),t("strong",{style:{"text-align":"left"}},"C"),t("span",null,"—"),t("span",null,"待"),t("span",null,"待"),t("span",null,"待"),t("span",null,"待"),t("strong",{style:{"border-radius":"4px",background:"var(--vp-c-brand-soft)"}},"●"),t("strong",{style:{"border-radius":"4px",background:"var(--vp-c-brand-soft)"}},"◎")]),t("strong",null,"連続バッチング"),t("div",{style:{display:"grid","grid-template-columns":"3.4em repeat(7, minmax(0, 1fr))",gap:"0.22rem","text-align":"center"}},[t("span",{style:{"text-align":"left"}},"時刻"),t("span",null,"2"),t("span",null,"3"),t("span",null,"4"),t("span",null,"5"),t("span",null,"6"),t("span",null,"7"),t("span",null,"8"),t("strong",{style:{"text-align":"left"}},"A"),t("strong",{style:{"border-radius":"4px",background:"var(--vp-c-brand-soft)"}},"●"),t("strong",{style:{"border-radius":"4px",background:"var(--vp-c-brand-soft)"}},"◎"),t("span",null,"—"),t("span",null,"—"),t("span",null,"—"),t("span",null,"—"),t("span",null,"—"),t("strong",{style:{"text-align":"left"}},"B"),t("strong",{style:{"border-radius":"4px",background:"var(--vp-c-brand-soft)"}},"●"),t("strong",{style:{"border-radius":"4px",background:"var(--vp-c-brand-soft)"}},"●"),t("strong",{style:{"border-radius":"4px",background:"var(--vp-c-brand-soft)"}},"●"),t("strong",{style:{"border-radius":"4px",background:"var(--vp-c-brand-soft)"}},"●"),t("strong",{style:{"border-radius":"4px",background:"var(--vp-c-brand-soft)"}},"◎"),t("span",null,"—"),t("span",null,"—"),t("strong",{style:{"text-align":"left"}},"C"),t("span",null,"—"),t("span",null,"待"),t("strong",{style:{"border-radius":"4px",background:"var(--vp-c-brand-soft)"}},"●"),t("strong",{style:{"border-radius":"4px",background:"var(--vp-c-brand-soft)"}},"◎"),t("span",null,"—"),t("span",null,"—"),t("span",null,"—")])]),t("figcaption",{style:{"font-size":"0.875rem","margin-top":"0.65rem"}},"列の数字は反復が終わる時刻（ms）。●は出力1個、◎は最後の1個、待は到着後の待機、—はその回の出力なし。")],-1),r('<p>Aはどちらでも3 msで終了します。Cが2.5 msに着いたときはA・Bの反復が実行中です。固定バッチでは、3 msでAが終わっても、Bが6 msで終わるまでCを組に入れません。連続バッチングでは3 msの境界でAの枠にCを入れられ、Bの次の1トークンとCの最初の1トークンを同じ反復で処理します。この例では先に到着したBが6 msに終わり、後から参加したCは5 msで終わります。</p><h2 id="初回の待ち、出力間隔、処理量を分ける" tabindex="-1">初回の待ち、出力間隔、処理量を分ける <a class="header-anchor" href="#初回の待ち、出力間隔、処理量を分ける" aria-label="Permalink to &quot;初回の待ち、出力間隔、処理量を分ける&quot;">​</a></h2><p><strong>TTFT</strong>（Time to First Token）は最初の出力までの待ち時間です。この図ではサーバーへの到着から最初のトークンが出るまでを測ります。<strong>ITL</strong>（Inter-Token Latency）は、この例のように1トークンずつ出す場合の、隣り合う出力時刻の差です。<strong>処理量</strong>（スループット）は、ここでは全リクエストで1 msあたりに生成した出力トークン数です。<a href="https://arxiv.org/html/2403.02310#S2.SS4" target="_blank" rel="noreferrer">Sarathi-Serve原論文 §2.4</a> · <a href="/study/algorithms/llm-prefill-and-decode.html">待ち時間の測定点を分ける</a></p><table tabindex="0"><thead><tr><th>この図から数える値</th><th style="text-align:right;">固定バッチ</th><th style="text-align:right;">連続バッチング</th></tr></thead><tbody><tr><td>CのTTFT（2.5 msの到着から）</td><td style="text-align:right;">4.5 ms</td><td style="text-align:right;">1.5 ms</td></tr><tr><td>CのITL</td><td style="text-align:right;">1 ms</td><td style="text-align:right;">1 ms</td></tr><tr><td>最初の実行開始から全員完了まで</td><td style="text-align:right;">7 ms</td><td style="text-align:right;">5 ms</td></tr><tr><td>全体の出力トークン数</td><td style="text-align:right;">9個</td><td style="text-align:right;">9個</td></tr><tr><td>上の実行区間での処理量</td><td style="text-align:right;">約1.29個/ms</td><td style="text-align:right;">1.8個/ms</td></tr></tbody></table><p>Cの初出力が早まる理由は、待機していたCを早い境界で実行するからです。反復時間を両方式とも同じ1 msに置いたので、ITLは変わりません。全体では同じ9個の出力を短い時間で終えています。この数値は説明用で、入力長やバッチの大きさが違ってもGPU上の反復時間が一定という意味ではありません。</p><p>実際には、生成中の列が毎回選ばれるか、選ばれた反復にどれだけ時間がかかるかでも出力間隔が変わります。たとえば、上の図の3 msから始まる回が、Cの長いprefillを含んで3 msかかったとします。直前に3 msで出力したBの続きは6 msに出るため、その区間のITLは3 msになります。入力を小分けにして一部ずつdecodeと同じ回に入れる方法は、こうした反復時間の伸びを抑える工夫の一つです。<a href="https://arxiv.org/html/2403.02310#S3.SS2" target="_blank" rel="noreferrer">Sarathi-Serve原論文 §3.2・§4</a></p><h2 id="空きができても、入れられる件数には上限がある" tabindex="-1">空きができても、入れられる件数には上限がある <a class="header-anchor" href="#空きができても、入れられる件数には上限がある" aria-label="Permalink to &quot;空きができても、入れられる件数には上限がある&quot;">​</a></h2><p>図の2列は教材用の上限です。実際には最大同時列数に加え、一度に処理する入力のトークン数や、保持するKVキャッシュに使えるメモリが限られます。枠が空いていても、次の反復に必要な資源が足りないリクエストは待ちます。待機列から誰を先に選ぶかはスケジューラーの方針です。Orcaは先着順を基本とし、生成に必要なKV用の枠も見て参加を決めます。<a href="https://www.usenix.org/system/files/osdi22-yu.pdf#page=9" target="_blank" rel="noreferrer">YuらのOrca原論文 §4.2</a> · <a href="https://arxiv.org/html/2403.02310#S4.SS3" target="_blank" rel="noreferrer">Sarathi-Serve原論文 §4.3</a></p><p>同じ回に入る列が増えると、重みの読み出しを複数の列で活用できます。一方で長い文脈のKVも読むため、列を増やしたときの反復時間は負荷やハードウェアで変わります。全体の処理量と各リクエストのTTFT・ITLは、それぞれ同じ負荷・測定点で比較します。<a href="https://www.usenix.org/conference/osdi22/presentation/yu" target="_blank" rel="noreferrer">YuらのOrca原論文 §3・§6</a> · <a href="https://arxiv.org/html/2403.02310#S3" target="_blank" rel="noreferrer">Sarathi-Serve原論文 §3</a></p><h2 id="連続バッチング、pagedattention、投機的デコーディングの役割" tabindex="-1">連続バッチング、PagedAttention、投機的デコーディングの役割 <a class="header-anchor" href="#連続バッチング、pagedattention、投機的デコーディングの役割" aria-label="Permalink to &quot;連続バッチング、PagedAttention、投機的デコーディングの役割&quot;">​</a></h2><table tabindex="0"><thead><tr><th>仕組み</th><th>何を決めるか</th></tr></thead><tbody><tr><td>連続バッチング</td><td>次の反復に参加するリクエストを選ぶ</td></tr><tr><td><a href="/study/algorithms/paged-attention.html">PagedAttention</a></td><td>各列のKVを置いたブロックを引き、分散して置いたKVをAttentionから参照する</td></tr><tr><td><a href="/study/algorithms/speculative-decoding.html">投機的デコーディング</a></td><td>同じ列の続きの候補を本命モデルでまとめて評価し、確定できるトークンを選ぶ</td></tr></tbody></table><p>連続バッチングの入れ替えは、KVの置き方や出力トークンを選ぶ規則とは別の判断です。vLLMの原論文では、ブロックの割り当てと反復ごとの選択を組み合わせています。Orcaの論文は別のKV管理で反復単位のスケジューリングを説明しています。図の1反復1トークンは、単純なdecodeを使った比較の条件です。<a href="https://arxiv.org/html/2309.06180#S4.SS3" target="_blank" rel="noreferrer">KwonらのPagedAttention原論文 §4.3</a> · <a href="https://www.usenix.org/system/files/osdi22-yu.pdf#page=9" target="_blank" rel="noreferrer">YuらのOrca原論文 §4.2</a> · <a href="https://proceedings.mlr.press/v202/leviathan23a.html" target="_blank" rel="noreferrer">Leviathanらの投機的デコーディング原論文</a></p><h2 id="要点" tabindex="-1">要点 <a class="header-anchor" href="#要点" aria-label="Permalink to &quot;要点&quot;">​</a></h2><ul><li>固定バッチはメンバーを開始時に決め、連続バッチングは反復の境界ごとに実行する列を選び直します。</li><li>短いリクエストが先に終わると、残りの生成中に待機中のリクエストを入れられます。入れられる数は計算とメモリの予算に左右されます。</li><li>初回応答は到着から最初の出力まで、生成中の待ちは出力間隔、全体の処理量は時間あたりの出力数として読み分けます。</li><li>連続バッチングは実行する列、PagedAttentionはKVの配置、投機的デコーディングは候補列の検証を扱います。</li></ul><h2 id="理解度チェック" tabindex="-1">理解度チェック <a class="header-anchor" href="#理解度チェック" aria-label="Permalink to &quot;理解度チェック&quot;">​</a></h2><details class="details custom-block"><summary>Cが2.5 msに届いたその瞬間、すぐAとの入れ替えはできる？</summary><p>図では2 msからの反復が実行中です。Aが3 msで完了した後に、次の反復へCを入れます。</p></details><details class="details custom-block"><summary>Cの最初のトークンが早まれば、Bがより短い間隔で出力する？</summary><p>図ではBの出力時刻はどちらも2、3、4、5、6 msです。実際の出力間隔は、Bを処理する反復の間隔と、その回の処理時間にも左右されます。</p></details><h2 id="検証範囲" tabindex="-1">検証範囲 <a class="header-anchor" href="#検証範囲" aria-label="Permalink to &quot;検証範囲&quot;">​</a></h2><p>2026年11月21日にOrcaなどの原論文を確認しました。WindowsのPython 3.12.4で図の両方式を反復ごとに進め、各列の出力時刻、TTFTとITL、処理量、長い反復の例の値を検算しました。時刻は説明用です。実機のGPU、推論サービスやネットワークでのレイテンシ・処理量は測っていません。</p><h2 id="関連項目" tabindex="-1">関連項目 <a class="header-anchor" href="#関連項目" aria-label="Permalink to &quot;関連項目&quot;">​</a></h2><ul><li><a href="/study/algorithms/llm-prefill-and-decode.html">LLM推論のprefillとdecode</a> — 入力処理と逐次生成、待ち時間の測定区間を読む。</li><li><a href="/study/algorithms/paged-attention.html">PagedAttention</a> — メモリ予算内で各リクエストのKVをどこに置くかを追う。</li><li><a href="/study/algorithms/speculative-decoding.html">投機的デコーディング</a> — 一つの列について、複数の候補トークンを一度に評価する仕組みを読む。</li></ul><h2 id="参考資料" tabindex="-1">参考資料 <a class="header-anchor" href="#参考資料" aria-label="Permalink to &quot;参考資料&quot;">​</a></h2><ul><li><a href="https://www.usenix.org/conference/osdi22/presentation/yu" target="_blank" rel="noreferrer">Gyeong-In Yuほか — Orca: A Distributed Serving System for Transformer-Based Generative Models（OSDI 2022）</a> — 反復単位のスケジューリングと、長さの異なる列をまとめて処理する設計。</li><li><a href="https://arxiv.org/html/2403.02310" target="_blank" rel="noreferrer">Amey Agrawalほか — Taming Throughput-Latency Tradeoff in LLM Inference with Sarathi-Serve（OSDI 2024）</a> — prefillとdecodeの計算コスト、出力間隔、入力の分割。</li><li><a href="https://arxiv.org/abs/2309.06180" target="_blank" rel="noreferrer">Woosuk Kwonほか — Efficient Memory Management for Large Language Model Serving with PagedAttention（SOSP 2023）</a> — KVのブロック割り当てと各反復の実行。</li><li><a href="https://proceedings.mlr.press/v202/leviathan23a.html" target="_blank" rel="noreferrer">Yaniv Leviathan, Matan Kalman, Yossi Matias — Fast Inference from Transformers via Speculative Decoding（ICML 2023）</a> — 候補列の一括評価と採択。</li></ul>',23)])])}const m=e(s,[["render",o]]);export{c as __pageData,m as default};
